CREATE TABLE users(id INTEGER PRIMARY KEY,username TEXT UNIQUE NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('citizen','officer','admin')),pass_hash TEXT NOT NULL,created INTEGER NOT NULL,approval_status TEXT NOT NULL DEFAULT 'active' CHECK(approval_status IN('active','pending','rejected')),email TEXT,residential_address TEXT,phone TEXT,suspended INTEGER NOT NULL DEFAULT 0 CHECK(suspended IN(0,1)),suspension_reason TEXT,suspended_at INTEGER,suspended_by INTEGER REFERENCES users(id),review_flag_reason TEXT,review_flagged_at INTEGER,review_flagged_by INTEGER REFERENCES users(id),passkey_user_handle TEXT,passkey_credential TEXT,passkey_label TEXT,passkey_created INTEGER,passkey_last_used INTEGER,admin_setup_hash TEXT,admin_setup_expires INTEGER,two_step_enabled INTEGER NOT NULL DEFAULT 0 CHECK(two_step_enabled IN(0,1)),face_vault TEXT,face_sha256 TEXT,face_mime TEXT CHECK(face_mime IN('image/jpeg','image/png') OR face_mime IS NULL),face_updated INTEGER);
CREATE TABLE cases(id INTEGER PRIMARY KEY,ref TEXT,citizen_id INTEGER NOT NULL REFERENCES users(id),title TEXT NOT NULL,type TEXT NOT NULL,description TEXT NOT NULL,location TEXT,status TEXT NOT NULL DEFAULT 'Reported',officer_id INTEGER REFERENCES users(id),created INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE case_events(id INTEGER PRIMARY KEY,case_id INTEGER NOT NULL REFERENCES cases(id),text TEXT NOT NULL,by_name TEXT NOT NULL,ts INTEGER NOT NULL);
CREATE TABLE evidence(id INTEGER PRIMARY KEY,case_id INTEGER NOT NULL REFERENCES cases(id),uploader_id INTEGER NOT NULL,filename TEXT NOT NULL,size INTEGER NOT NULL,vault TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Pending',note TEXT,reviewer_id INTEGER,created INTEGER NOT NULL);
CREATE TABLE affidavits(id INTEGER PRIMARY KEY,case_id INTEGER NOT NULL REFERENCES cases(id),citizen_id INTEGER NOT NULL,vault TEXT NOT NULL,sha256 TEXT NOT NULL,stamped_vault TEXT,status TEXT NOT NULL DEFAULT 'Pending',officer_id INTEGER,created INTEGER NOT NULL,certified_at INTEGER);
CREATE TABLE sos(id INTEGER PRIMARY KEY,citizen_id INTEGER NOT NULL REFERENCES users(id),lat REAL,lng REAL,status TEXT NOT NULL DEFAULT 'Open',ack_by INTEGER,created INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE audit(id INTEGER PRIMARY KEY,ts INTEGER NOT NULL,user_id INTEGER,username TEXT,action TEXT NOT NULL,detail TEXT,ip TEXT,ua TEXT);
CREATE TABLE admin_lock(id INTEGER PRIMARY KEY CHECK(id=1),session_id TEXT NOT NULL,user_id INTEGER NOT NULL,last_seen INTEGER NOT NULL);
CREATE INDEX ix_cases_c ON cases(citizen_id);CREATE INDEX ix_cases_o ON cases(officer_id);CREATE INDEX ix_ev_c ON evidence(case_id);
